// Marstek Capacity Monitor: battery card, overview card and dashboard.
// Loaded by the integration itself; no button-card and no resources needed.
// GENERATED by scripts/build_card.py from dashboard/button-card/marstek_capacity_templates.yaml
// (the card logic) and scripts/card_glue.js (this frame). Do not edit by hand.

const MC_VERSION = "__VERSION__";
const MC_DOMAIN = "marstek_capacity_monitor";
const MC_DOCS = "https://github.com/satscan1/marstek-capacity-monitor/blob/main/docs";

// Names come from the device registry and the card config: escape them.
function mcEsc(text) {
  return String(text).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

// The sensors a card reads (fixed list, so no scanning of all states).
const MC_KEYS = ["measured_capacity", "capacity_pct", "expected_capacity", "warranty_status",
  "warranty_end", "margin", "last_full_discharge", "last_full_charge", "monitor_status", "cell_spread"];

// Batteries of this integration, found through the entity registry.
// Cached per registry object: HA replaces it only when the registry changes.
let mcCache = { entities: null, devices: null, list: [] };
function mcBatteries(hass) {
  if (!hass) return [];
  if (mcCache.entities === hass.entities && mcCache.devices === hass.devices) return mcCache.list;
  const out = [];
  for (const [eid, ent] of Object.entries((hass && hass.entities) || {})) {
    if (ent.platform !== MC_DOMAIN) continue;
    const m = /^sensor\.marstek_(.+)_monitor_status$/.exec(eid);
    if (!m) continue;
    const dev = ent.device_id && hass.devices ? hass.devices[ent.device_id] : null;
    out.push({ id: m[1], name: (dev && (dev.name_by_user || dev.name)) || m[1].toUpperCase() });
  }
  out.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
  mcCache = { entities: hass.entities, devices: hass.devices, list: out };
  return out;
}

function mcLang(hass, config) {
  if (config && config.lang) return config.lang;
  const l = (hass && ((hass.locale && hass.locale.language) || hass.language)) || "en";
  return l.startsWith("nl") ? "nl" : l.startsWith("de") ? "de" : "en";
}

function batteryBody(states, variables, ctx) {
/*__BATTERY_BODY__*/
}

function overviewBody(states, variables) {
/*__OVERVIEW_BODY__*/
}

const MC_STYLE = `
  :host { display: block; height: 100%; }
  ha-card { background: #1e2128; border: 1px solid #333744; border-radius: 12px;
    padding: 14px; color: #e8eaed; font-size: 13px; height: 100%; box-sizing: border-box;
    text-align: left; white-space: normal; }
  [data-mc] { cursor: pointer; }
`;

class MarstekCapacityBase extends HTMLElement {
  setConfig(config) {
    this._config = { ...(config || {}) };
    this._sig = null;
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    const sig = this._signature();
    if (sig !== this._sig) {
      this._sig = sig;
      this._render();
    }
  }

  get hass() {
    return this._hass;
  }

  // Only redraw when one of our own sensors changed (HA replaces a state
  // object on every change, so comparing the objects is cheap).
  _signature() {
    if (!this._hass) return "";
    const ids = this._ids();
    const objs = [];
    for (const id of ids) for (const k of MC_KEYS) objs.push(this._hass.states[`sensor.marstek_${id}_${k}`]);
    const same = this._lastObjs && this._lastObjs.length === objs.length
      && objs.every((o, i) => o === this._lastObjs[i]);
    if (!same) {
      this._lastObjs = objs;
      this._rev = (this._rev || 0) + 1;
    }
    return `${mcLang(this._hass, this._config)}|${ids.join(",")}|${this._rev}`;
  }

  _render() {
    if (!this._hass || !this._config) return;
    if (!this.shadowRoot) {
      this.attachShadow({ mode: "open" });
      this.shadowRoot.addEventListener("click", (ev) => {
        const el = ev.composedPath().find((n) => n.dataset && n.dataset.mc);
        if (!el) return;
        ev.stopPropagation();
        this._action(el.dataset.mc);
        this._render();
      });
    }
    let html;
    try {
      html = this._html();
    } catch (err) {
      html = `<span style="color:#ef5350">Marstek Capacity Monitor: ${mcEsc(err)}</span>`;
    }
    this.shadowRoot.innerHTML = `<style>${MC_STYLE}</style><ha-card>${html}</ha-card>`;
  }

  _action(_act) {}

  getCardSize() {
    return 6;
  }
}

class MarstekCapacityCard extends MarstekCapacityBase {
  static getStubConfig(hass) {
    const b = mcBatteries(hass)[0];
    return b ? { battery: b.id } : {};
  }

  _battery() {
    const found = mcBatteries(this._hass);
    const id = this._config.battery || (found[0] && found[0].id);
    const name = this._config.name || (found.find((b) => b.id === id) || {}).name;
    return { id: id && String(id).replace(/[^a-z0-9_]/gi, ""), name: name ? mcEsc(name) : name };
  }

  _ids() {
    const b = this._battery();
    return b.id ? [b.id] : [];
  }

  _action(act) {
    if (act.includes("_mcChart")) this._chart = !this._chart;
  }

  _html() {
    const b = this._battery();
    const lang = mcLang(this._hass, this._config);
    if (!b.id) {
      return {
        nl: "Nog geen batterij gevonden. Voeg er een toe via Instellingen → Apparaten en diensten → Voeg integratie toe → Marstek Capacity Monitor.",
        de: "Noch keine Batterie gefunden. Füge eine hinzu: Einstellungen → Geräte & Dienste → Integration hinzufügen → Marstek Capacity Monitor.",
      }[lang] || "No battery found yet. Add one via Settings → Devices & services → Add integration → Marstek Capacity Monitor.";
    }
    const variables = { battery: b.id, name: b.name, lang, months: this._config.months || 6, demo: this._config.demo };
    return batteryBody(this._hass.states, variables, { chart: this._chart, width: this.offsetWidth });
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }
}

class MarstekCapacityOverviewCard extends MarstekCapacityBase {
  static getStubConfig() {
    return {};
  }

  _list() {
    const found = mcBatteries(this._hass);
    const wanted = this._config.batteries;
    if (!wanted) return found.map((b) => ({ id: b.id, name: mcEsc(b.name) }));
    return wanted.map((x) => {
      const b = typeof x === "string" ? { id: x } : x;
      const name = b.name || (found.find((f) => f.id === b.id) || {}).name;
      return { id: String(b.id).replace(/[^a-z0-9_]/gi, ""), name: name ? mcEsc(name) : name };
    });
  }

  _ids() {
    return this._list().map((b) => b.id);
  }

  _html() {
    const lang = mcLang(this._hass, this._config);
    const list = this._list();
    if (!list.length) {
      return { nl: "Nog geen batterij gevonden.", de: "Noch keine Batterie gefunden." }[lang] || "No battery found yet.";
    }
    const months = this._config.months || (list.length <= 2 ? 3 : 6);
    return overviewBody(this._hass.states, { batteries: list, lang, months, demo: this._config.demo });
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }
}

